#include <kraken/KrakenEngine.hpp>

int main() {
    kn::init();
    kn::window::create("Spritesheet Animation", 800, 450);
    { // Destroy GPU resources before quitting the engine.
        kn::Texture sheet("assets/player_sheet.png");
        kn::Transform player;
        player.pos = kn::Vec2(384, 208);
        kn::AnimationController controller;
        controller.addStrips(32, 32, {
            {"idle", 6, 6}, {"walk", 6, 8}, {"attack", 4, 8}
        });
        controller.play("idle");
        while (kn::window::isOpen()) {
            kn::event::poll();
            if (kn::key::isPressed(kn::Keycode::Right) ||
                kn::key::isPressed(kn::Keycode::Left)) {
                controller.set("walk");
            } else {
                controller.set("idle");
            }
            kn::DrawOptions options;
            options.source = controller.getFrameArea();
            kn::renderer::clear();
            kn::renderer::draw(sheet, player, options);
            kn::renderer::present();
        }
    }
    kn::quit();
}

