// Avoid this lifetime error:
// A Text must not outlive the Font it references.
auto makeLabel() {
    kn::Font font("fonts/arial.ttf", 24);
    return std::make_unique<kn::Text>(font, "Ready");
    // font is destroyed here; the returned Text has a dangling reference.
}

struct Label {
    kn::Font font{"fonts/arial.ttf", 24};
    kn::Text text{font, "Ready"};
    // Members are destroyed in reverse order: Text, then Font.
    Label() = default;
    Label(const Label&) = delete;
    Label& operator=(const Label&) = delete;
};
auto label = std::make_unique<Label>(); // Stable address for Font.

