#include <kraken/KrakenEngine.hpp>
#include <string>

int main() {
    constexpr int width = 800, height = 600;
    const kn::Vec2 size(width, height);
    kn::init();
    kn::window::create("Text Example", width, height);
    kn::time::setTarget(60);
    { // Fonts outlive their Text objects; all are destroyed before quit().
        kn::Font small("fonts/arial.ttf", 20);
        kn::Font medium("fonts/arial.ttf", 32);
        kn::Font large("fonts/arial.ttf", 64);
        kn::Text title(large, "SPACE SHOOTER");
        title.setColor(kn::Color(100, 200, 255));
        kn::Text instructions(medium, "Press SPACE to start");
        kn::Text scoreText(small, "Score: 0");
        scoreText.setColor(kn::Color::YELLOW);
        kn::Text fpsText(small);
        fpsText.setColor(kn::Color::GRAY);
        int score = 0;
        bool started = false;
        kn::Rect player(0, 0, 40, 40);
        player.setCenter(kn::Vec2(width / 2, height - 100));
        while (kn::window::isOpen()) {
            kn::event::poll();
            const double dt = kn::time::getDelta();
            kn::renderer::clear(kn::Color(20, 20, 40));
            if (!started) {
                if (kn::key::isJustPressed(kn::Keycode::Space)) started = true;
                title.draw(size * kn::Vec2(0.5, 1.0 / 3.0), kn::Anchor::CENTER);
                instructions.draw(size / 2, kn::Anchor::CENTER);
            } else {
                if (kn::key::isPressed(kn::Scancode::A)) player.x -= 300 * dt;
                if (kn::key::isPressed(kn::Scancode::D)) player.x += 300 * dt;
                scoreText.setText("Score: " + std::to_string(++score));
                kn::draw::rect(player, kn::Color::GREEN);
                scoreText.draw(kn::Vec2(10));
                fpsText.setText("FPS: " + std::to_string(int(kn::time::getFPS())));
                fpsText.draw(kn::Vec2(width - 10, 10), kn::Anchor::TOP_RIGHT);
            }
            kn::renderer::present();
        }
    }
    kn::quit();
}

